package com.zerostreams.app;
import android.content.Intent;import android.webkit.WebView;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class SportsPlayerTest {
 WebView find(View view){if(view instanceof WebView)return(WebView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){WebView result=find(group.getChildAt(i));if(result!=null)return result;}}return null;}
 android.widget.Spinner spinner(View view){if(view instanceof android.widget.Spinner)return (android.widget.Spinner)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){android.widget.Spinner result=spinner(group.getChildAt(i));if(result!=null)return result;}}return null;}
 String js(ActivityScenario<SportsPlayerActivity> scenario,String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> value=new AtomicReference<>();scenario.onActivity(a->find(a.getWindow().getDecorView()).evaluateJavascript(code,r->{value.set(r);latch.countDown();}));Assert.assertTrue(latch.await(8,TimeUnit.SECONDS));return value.get();}
 @Test public void urlAndIframeHtmlDecodeVideoAndFullscreenBack()throws Exception{java.net.ServerSocket server=new java.net.ServerSocket(0,8,java.net.InetAddress.getByName("127.0.0.1"));String html="<video autoplay muted playsinline src='data:video/mp4;base64,' ontimeupdate=\"if(this.currentTime>1){document.title='playing';parent.postMessage('playing','*')}\"></video>";byte[] body=html.getBytes("UTF-8");Thread serving=new Thread(()->{while(!server.isClosed())try(java.net.Socket socket=server.accept()){socket.setSoTimeout(5000);java.io.BufferedReader reader=new java.io.BufferedReader(new java.io.InputStreamReader(socket.getInputStream()));String line;while((line=reader.readLine())!=null&&!line.isEmpty()){}java.io.OutputStream out=socket.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: "+body.length+"\r\nConnection: close\r\n\r\n").getBytes("UTF-8"));out.write(body);}catch(Exception ignored){}});serving.start();String url="http://127.0.0.1:"+server.getLocalPort();try{for(String embed:new String[]{url,"<iframe src='"+url+"' allow='autoplay; fullscreen' allowfullscreen></iframe><script>addEventListener('message',e=>document.title=e.data)</script>"}){JSONArray sources=new JSONArray().put(new JSONObject().put("source_tag","Playback fixture").put("iframe",embed));Intent intent=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),SportsPlayerActivity.class).putExtra("sources",sources.toString()).putExtra("base",url);try(ActivityScenario<SportsPlayerActivity> scenario=ActivityScenario.launch(intent)){String title="";for(int i=0;i<100;i++){title=js(scenario,"document.title");if("\"playing\"".equals(title))break;Thread.sleep(100);}Assert.assertEquals("\"playing\"",title);AtomicBoolean hidden=new AtomicBoolean();scenario.onActivity(a->{WebView web=find(a.getWindow().getDecorView());web.getWebChromeClient().onShowCustomView(new android.widget.FrameLayout(a),()->hidden.set(true));a.onBackPressed();Assert.assertFalse(a.isFinishing());});Assert.assertTrue(hidden.get());}}}finally{server.close();serving.join(3000);}}
 @Test public void nativeTorrentEngineAndMagnetStart(){String m=TorrentDownloads.magnet("magnet:?xt=urn:btih:"+"0123456789abcdef0123456789abcdef01234567"+"&dn=fixture");Assert.assertTrue(m.startsWith("magnet:?"));org.libtorrent4j.SessionManager engine=new org.libtorrent4j.SessionManager();try{engine.start();Assert.assertTrue(engine.isRunning());}finally{engine.stop();}}
 @Test public void htmlPlayerKeepsScriptsAdsAndAlternateSources()throws Exception{JSONArray sources=new JSONArray().put(new JSONObject().put("source_tag","Main fixture").put("iframe","<div id='ad'>Provider advertisement</div><button id='control' onclick=\"document.body.dataset.clicked='yes'\">Play fixture</button><script>localStorage.setItem('sports-fixture','kept');document.body.dataset.ready='yes'</script>")).put(new JSONObject().put("source_tag","Alternative fixture").put("iframe","<div id='alternate'>Alternate loaded</div>"));Intent intent=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),SportsPlayerActivity.class).putExtra("sources",sources.toString()).putExtra("base","https://api.ppv.st");try(ActivityScenario<SportsPlayerActivity> scenario=ActivityScenario.launch(intent)){String ready="";for(int i=0;i<40;i++){ready=js(scenario,"document.body.dataset.ready");if("\"yes\"".equals(ready))break;Thread.sleep(100);}Assert.assertEquals("\"yes\"",ready);Assert.assertEquals("\"Provider advertisement\"",js(scenario,"document.getElementById('ad').textContent"));Assert.assertEquals("\"kept\"",js(scenario,"localStorage.getItem('sports-fixture')"));Assert.assertEquals("\"undefined\"",js(scenario,"typeof window.__zeroBlockAds"));scenario.onActivity(a->spinner(a.getWindow().getDecorView()).setSelection(1));String alternative="";for(int i=0;i<100;i++){alternative=js(scenario,"document.getElementById('alternate')&&document.getElementById('alternate').textContent");if("\"Alternate loaded\"".equals(alternative))break;Thread.sleep(100);}Assert.assertEquals("\"Alternate loaded\"",alternative);scenario.onActivity(a->{a.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));a.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_RIGHT));a.onBackPressed();});}}
}
